/*
Write a C++ function `int minimum_moves(int n, int m)` that, given the dimensions `n` and `m` of a rectangular grid, returns the minimum number of moves required to color the entire grid black starting from an all-white grid, where each move selects any single cell and flips the color of all cells in the same row and column (including itself). The function must handle any positive integer dimensions up to `10^9`. The base problem is: if the grid is a single cell (1×1), zero moves are needed; if one dimension is 1 (but not both), exactly one move is needed; otherwise, two moves suffice. Implement the function to match this behavior exactly.
*/
#include <algorithm>
#include <cstdint>

// Returns the minimum number of moves to black out an n x m grid
// where each move flips an entire row and column.
int minimum_moves(int n, int m) {
    if (n == 1 && m == 1) {
        return 0;
    }
    if (n == 1 || m == 1) {
        return 1;
    }
    return 2;
}
#include <cassert>

int main() {
    assert(minimum_moves(1, 1) == 0);
    assert(minimum_moves(1, 5) == 1);
    assert(minimum_moves(7, 1) == 1);
    assert(minimum_moves(2, 2) == 2);
    assert(minimum_moves(3, 4) == 2);
    assert(minimum_moves(1, 2) == 1);
    assert(minimum_moves(1000000000, 1) == 1);
    assert(minimum_moves(1000000000, 1000000000) == 2);
    assert(minimum_moves(2, 1) == 1);
    assert(minimum_moves(5, 5) == 2);
    return 0;
}
